import{_ as t,o,c as d,a3 as a}from"./chunks/framework.CCylkYel.js";const u=JSON.parse('{"title":"Connect","description":"","frontmatter":{},"headers":[],"relativePath":"developers/connecting.md","filePath":"developers/connecting.md"}'),r={name:"developers/connecting.md"};function s(c,e,n,i,p,l){return o(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="connect" tabindex="-1">Connect <a class="header-anchor" href="#connect" aria-label="Permalink to &quot;Connect&quot;">​</a></h1><p>s32 talks to a real S32 (<code>--usb</code>) or to a simulator inside the s32 process (<code>--loopback</code>).</p><table tabindex="0"><thead><tr><th></th><th><code>--loopback</code></th><th><code>--usb</code></th></tr></thead><tbody><tr><td>Target</td><td>Simulator</td><td>The S32 on USB</td></tr><tr><td>Changes last</td><td>Until the process ends</td><td>Live on the S32. <code>project save</code> keeps them</td></tr><tr><td>Device types</td><td>A short sample set</td><td>Every device the firmware has</td></tr></tbody></table><p>With no flag, s32 uses the S32 when one is plugged in and the simulator when not.</p><h2 id="usb" tabindex="-1">USB <a class="header-anchor" href="#usb" aria-label="Permalink to &quot;USB&quot;">​</a></h2><p>Only one program can hold the editor interface. Close the web editor (any browser tab using it) first.</p><p>Holding the interface means full control: s32 can read and overwrite projects, change mappings and capture the screen. There is no password. <code>pull</code> a copy of the project you care about before you start.</p><p>These commands ask first. <code>--yes</code> skips the question, and <a href="./simulator#script"><code>--script</code></a> never asks:</p><table tabindex="0"><thead><tr><th>Command</th><th>Effect</th></tr></thead><tbody><tr><td><code>push --activate</code></td><td>Replaces the project you are playing</td></tr><tr><td><code>project delete</code></td><td>Deletes a stored project</td></tr><tr><td><code>project load</code></td><td>Replaces the project you are playing</td></tr><tr><td><code>rack clear</code></td><td>Removes every device in the rack</td></tr><tr><td><code>globals set</code></td><td>Writes project clock settings and S32 settings</td></tr></tbody></table><p>If a run is stopped halfway (Ctrl-C), the next run still works and ends the stopped push or pull.</p><p><code>S32_DEBUG=1</code> prints every message s32 sends and receives.</p>',11)])])}const m=t(r,[["render",s]]);export{u as __pageData,m as default};
